function lesson8Dialogue(){app.innerHTML=intro('HỘI THOẠI · BÀI 8','Nấu ăn và trò chuyện về ngoại ngữ.','Hai hội thoại được chép lại từ các trang bạn gửi.')+lesson2VoiceControls()+'<button class="btn secondary" id="pinyin">'+(showPinyin?'Ẩn':'Hiện')+' pinyin</button>'+lesson8Data.dialogues.map(([title,lines],d)=>'<h2>'+title+'</h2><button class="btn secondary" data-lesson8-full="'+d+'">▶ Nghe toàn hội thoại</button>'+lines.map(([name,zh,py,vi],i)=>'<article class="dialogue"><small>'+name+'</small><button class="text-button" data-lesson8-line="'+d+','+i+'" aria-label="Nghe câu '+(i+1)+'">▶</button><p class="han">'+zh+'</p>'+(showPinyin?'<p class="pinyin">'+py+'</p>':'')+'<p>'+vi+'</p></article>').join('')).join('')+lesson8References(6,9);bindLesson2Voice(lesson8Data.dialogues[0][1].map(l=>l[1]).join(' '));document.querySelector('#pinyin').onclick=()=>{stopWordAudio();showPinyin=!showPinyin;lesson8Dialogue();};document.querySelectorAll('[data-lesson8-line]').forEach(b=>b.onclick=()=>{const[d,i]=b.dataset.lesson8Line.split(',').map(Number);lesson2Speak(lesson8Data.dialogues[d][1][i][1]);});document.querySelectorAll('[data-lesson8-full]').forEach(b=>b.onclick=()=>lesson2Speak(lesson8Data.dialogues[Number(b.dataset.lesson8Full)][1].map(l=>l[1]).join(' ')));}
function lesson8BTNCMarkup(file){const group=lesson8BTNC.find(g=>g.file===file);if(!group)return '<p class="sub">File chính Q2B8; xem phần đáp án BTNC trên trang tham khảo bên dưới.</p>'+lesson8BTNCReference();const id=lesson8BTNC.indexOf(group),saved=state.lesson8Exercises?.['btnc'+id]||{};return '<details class="lesson2-answer-key"><summary>Luyện nghe với 5 câu hỏi</summary><p class="sub">Câu hỏi tự luyện biên soạn từ bản ghi lời nghe, không phải bộ lựa chọn của đề BTNC gốc.</p><form id="lesson8BTNCForm'+id+'">'+group.questions.map((q,i)=>'<fieldset class="question"><legend>'+q[0]+'</legend>'+q[1].map((v,j)=>'<label><input type="radio" name="l8nc'+id+'q'+i+'" value="'+j+'" '+(String(saved[i]?.answer)===String(j)?'checked':'')+'> '+v+'</label>').join('')+'<div id="lesson8BTNCFeedback'+id+'-'+i+'"></div></fieldset>').join('')+'<button class="btn" type="submit">Kiểm tra</button><p id="lesson8BTNCResult'+id+'" role="status"></p></form></details><details class="lesson2-answer-key"><summary>Bản ghi lời nghe và đáp án BTNC gốc</summary>'+group.transcript.map((t,i)=>'<p lang="zh-CN" style="white-space:pre-line">'+(i+1)+'. '+esc(t)+'</p>').join('')+'<p><b>Đáp án '+group.title+':</b> '+group.key.map((k,i)=>(i+1)+'. '+k).join(' · ')+'</p><p class="sub">Các chữ cái dùng đối chiếu với đề BTNC gốc; câu tự luyện phía trên có thứ tự lựa chọn riêng.</p>'+lesson8BTNCReference()+'</details>';}
function lesson8BTNCReference(){return '<details class="lesson2-reference"><summary>Xem trang đáp án BTNC bài 8</summary><img loading="lazy" style="max-width:100%;height:auto" src="images/lesson8/btnc-answers-page19.png" alt="Đáp án BTNC bài 8, trang 19 của PDF"></details>';}
function bindLesson8BTNC(){lesson8BTNC.forEach((group,id)=>{document.querySelector('#lesson8BTNCForm'+id).onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),records={};let count=0;group.questions.forEach((q,i)=>{const answer=form.get('l8nc'+id+'q'+i),correct=answer!==null&&Number(answer)===q[2];records[i]={answer,correct};count+=correct?1:0;document.querySelector('#lesson8BTNCFeedback'+id+'-'+i).innerHTML='<div class="feedback '+(correct?'good':'bad')+'">'+(correct?'✓ Chính xác':'Đáp án: '+esc(q[1][q[2]]))+'</div>';});state.lesson8Exercises=state.lesson8Exercises||{};state.lesson8Exercises['btnc'+id]=records;save();document.querySelector('#lesson8BTNCResult'+id).textContent='Đúng '+count+' / 5 câu.';};});}

const lesson8SourcePages=["91","92","93","94","95","96","97","98","99","100","101","102","103"];
function lesson8References(first=1,last=13){return '<details class="lesson2-reference"><summary>Xem trang giáo trình gốc</summary>'+Array.from({length:last-first+1},(_,i)=>'<figure><img loading="lazy" src="images/lesson8/source-'+(first+i)+'.png" alt="Bài 8 · ảnh nguồn '+(first+i)+'"><figcaption>Trang '+lesson8SourcePages[first+i-1]+'</figcaption></figure>').join('')+'</details>';}
function lesson8Home(){app.innerHTML=intro('HSK2 · LESSON 8',lesson8Data.title,lesson8Data.pinyin+' · '+lesson8Data.vi)+'<section class="hero"><div><h2>Bạn biết làm những gì?</h2><p>Nói về kỹ năng nấu ăn, ngoại ngữ và sở thích.</p><a class="btn" href="#words">Học 16 mục từ →</a></div><div class="hero-mark" aria-hidden="true">会</div></section><div class="stats"><div class="stat"><small>TỪ ĐÃ NHỚ</small><strong>'+state.known.length+'<small> / 16</small></strong></div><div class="stat"><small>HỘI THOẠI</small><strong>02</strong></div><div class="stat"><small>TRANG GIÁO TRÌNH</small><strong>91–103</strong></div></div><div class="grid">'+[['words','Từ vựng','Nghe & gõ · Flashcard · Ghép từ'],['grammar','Ngữ pháp','会 · 除了……以外，还……'],['dialogue','Hội thoại','Mời ăn tối · Nói về ngoại ngữ'],['practice','Luyện tập','Điền từ · Đọc hiểu · Kỹ năng · Phỏng vấn'],['listening','Luyện nghe','Bốn file Q2B8 · Bản ghi BTNC · Tự luyện'],['writing','Luyện viết','Chữ Hán trong bài 8']].map(([id,title,desc])=>'<a class="card card-link" href="#'+id+'"><h3>'+title+' ↗</h3><p>'+desc+'</p></a>').join('')+'</div><article class="card grammar"><h2>Khởi động</h2><p>除了汉语以外，你还会说什么外语？<br>你会做菜吗？你会做什么菜？<br>你会唱歌吗？你会唱什么歌？</p></article>'+lesson8References();}
function lesson8Grammar(){app.innerHTML=intro('NGỮ PHÁP · BÀI 8','Nói về kỹ năng và bổ sung thông tin.','Hai điểm ngữ pháp trong bài, kèm ví dụ và giải thích tiếng Việt.')+'<article class="card grammar"><h2>01 · 会: kỹ năng đã học</h2><div class="pattern">Chủ ngữ + 会 + động từ (+ tân ngữ)</div><p>会 chỉ kỹ năng đạt được qua học tập hoặc luyện tập. Phủ định dùng 不会.</p><p lang="zh-CN">我会唱中文歌。<br>欧文会说英语，还会说法语。<br>他不会说汉语。<br>田中不会做饭。</p><h3>Biết một chút</h3><p>Đặt 一点儿 sau động từ, hoặc giữa động từ và tân ngữ.</p><p lang="zh-CN">我会说一点儿汉语。<br>我会喝一点儿。</p><p class="sub">会 nhấn mạnh kỹ năng; 可以 thường dùng khi xin phép hoặc nhờ giúp; 想 diễn tả mong muốn.</p></article><article class="card grammar"><h2>02 · 除了……以外，还……</h2><div class="pattern">除了 + nội dung A + 以外，chủ ngữ + 还 + nội dung B</div><p>Ngoài A ra, còn B; nội dung thứ hai được bổ sung cùng với nội dung thứ nhất.</p><p lang="zh-CN">除了英语以外，我还会说一点儿汉语。<br>除了北京以外，他还想去上海。<br>除了唱歌以外，他还喜欢跳舞。</p><p class="sub">Ngoài tiếng Anh, tôi còn nói được một chút tiếng Trung. · Ngoài Bắc Kinh, anh ấy còn muốn đến Thượng Hải. · Ngoài hát, anh ấy còn thích nhảy.</p></article><a class="btn" href="#practice">Luyện kỹ năng và sở thích →</a>'+lesson8References(3,5);}
let lesson8PracticeMode='vocab';
function gradeLesson8Exercise(mode,index,draft){const q=lesson8Data.exercises[mode][index],variants=[q[1]];if(mode==='vocab'&&index===2)variants.push('哪里');if(mode==='choose'&&index===0)variants.push('可以');return {correct:variants.some(a=>compareHanzi(draft,a).correct),answer:q[1],note:q[2]};}
function lesson8Practice(){app.innerHTML=intro('LUYỆN TẬP · BÀI 8','Bạn biết làm gì, thích những gì?','Luyện 会 và 除了……以外，还…… theo tranh, đoạn đọc và phỏng vấn.')+'<div class="toolbar lesson2-modes">'+[['vocab','Điền từ'],['reading','Đọc hiểu'],['choose','会 · 可以 · 想 · 要'],['pictures','Kỹ năng theo ảnh'],['photos','Thêm sở thích'],['shop','Phỏng vấn bạn học'],['summary','Tự tổng kết']].map(([id,title])=>'<button class="btn '+(lesson8PracticeMode===id?'':'secondary')+'" data-lesson8-mode="'+id+'">'+title+'</button>').join('')+'</div><div id="lesson8ExerciseArea"></div>';document.querySelectorAll('[data-lesson8-mode]').forEach(b=>b.onclick=()=>{lesson8PracticeMode=b.dataset.lesson8Mode;lesson8Practice();});renderLesson8ExerciseArea();}
function renderLesson8ExerciseArea(){const area=document.querySelector('#lesson8ExerciseArea'),mode=lesson8PracticeMode;if(mode==='pictures'){renderLesson8Skills(area);return;}if(mode==='photos'){renderLesson8Extension(area);return;}if(mode==='shop'){renderLesson8Shop(area);return;}if(mode==='summary'){area.innerHTML='<article class="card grammar"><h2>Từ ngữ và mẫu câu muốn nhớ</h2><label for="lesson8SummaryWords">Từ ngữ</label><textarea id="lesson8SummaryWords" rows="4"></textarea><label for="lesson8SummaryPatterns">Mẫu câu</label><textarea id="lesson8SummaryPatterns" rows="4"></textarea><p class="sub">Tự động lưu trong tiến độ Lesson 8.</p></article>'+lesson8References(13,13);for(const[id,key]of [['lesson8SummaryWords','words'],['lesson8SummaryPatterns','patterns']]){document.querySelector('#'+id).value=state.lesson8Summary?.[key]||'';document.querySelector('#'+id).oninput=e=>{state.lesson8Summary=state.lesson8Summary||{};state.lesson8Summary[key]=e.target.value;save();};}return;}
 const saved=state.lesson8Exercises?.[mode]||{};
 area.innerHTML=(mode==='reading'?'<article class="card grammar"><h2>Đoạn đọc</h2><p class="lesson2-reading" lang="zh-CN">'+lesson8Data.reading+'</p><p class="sub">Từ hỗ trợ: 红酒 (vang đỏ), 杯 (cốc/ly), 图书馆 (thư viện).</p></article>':'')+'<form id="lesson8ExerciseForm">'+lesson8Data.exercises[mode].map((q,i)=>'<article class="card grammar"><label for="lesson8Answer'+i+'">'+(i+1)+'. '+esc(q[0])+'</label><input class="lesson2-answer" id="lesson8Answer'+i+'" lang="zh-CN" placeholder="Gõ chữ Hán…" value="'+esc(saved[i]?.draft||'')+'"><div id="lesson8Feedback'+i+'" role="status"></div></article>').join('')+'<button class="btn" type="submit">Kiểm tra</button><p id="lesson8Result" role="status"></p></form>'+(mode==='reading'?'<h2>Chọn đáp án theo đoạn văn</h2><form id="lesson8ReadingQuiz">'+lesson8Data.exercises.comprehension.map((q,i)=>'<fieldset class="card question"><legend>'+q[0]+'</legend>'+q[1].map((v,j)=>'<label><input type="radio" name="l8reading'+i+'" value="'+j+'"> '+v+'</label>').join('')+'<div id="lesson8ReadingFeedback'+i+'"></div></fieldset>').join('')+'<button class="btn" type="submit">Kiểm tra đọc hiểu</button><p id="lesson8ReadingResult" role="status"></p></form>':'')+lesson8References(mode==='vocab'?2:12,mode==='vocab'?2:13);
 document.querySelector('#lesson8ExerciseForm').onsubmit=e=>{e.preventDefault();const records={};let count=0;lesson8Data.exercises[mode].forEach((q,i)=>{const draft=document.querySelector('#lesson8Answer'+i).value,r=gradeLesson8Exercise(mode,i,draft);records[i]={draft,correct:r.correct};count+=r.correct?1:0;document.querySelector('#lesson8Feedback'+i).innerHTML='<div class="feedback '+(r.correct?'good':'bad')+'">'+(r.correct?'✓ Chính xác':'Đáp án tham khảo: '+esc(r.answer))+'<br>'+esc(r.note)+'</div>';});state.lesson8Exercises=state.lesson8Exercises||{};state.lesson8Exercises[mode]=records;save();document.querySelector('#lesson8Result').textContent='Đúng '+count+' / '+lesson8Data.exercises[mode].length+' câu.';};
 if(mode==='reading')document.querySelector('#lesson8ReadingQuiz').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),records={};let count=0;lesson8Data.exercises.comprehension.forEach((q,i)=>{const answer=form.get('l8reading'+i),correct=answer!==null&&Number(answer)===q[2];records[i]={answer,correct};count+=correct?1:0;document.querySelector('#lesson8ReadingFeedback'+i).innerHTML='<div class="feedback '+(correct?'good':'bad')+'">'+(correct?'✓ Chính xác':'Đáp án: '+esc(q[1][q[2]]))+'</div>';});state.lesson8Exercises=state.lesson8Exercises||{};state.lesson8Exercises.comprehension=records;save();document.querySelector('#lesson8ReadingResult').textContent='Đúng '+count+' / '+lesson8Data.exercises.comprehension.length+' câu.';};
}

function lesson8Listening(){const groups=[{"title":"08-1 · Đến nhà bạn ăn tối","d":0,"tf":[["美京会做菜。","Đúng."],["美京和田中要去饭店吃晚饭。","Sai — đến nhà Mỹ Kinh."],["美京不会喝酒。","Sai — cô ấy thích vang đỏ."],["美京会做红酒。","Đúng."]],"questions":[["美京会做哪国菜？","韩国菜和中国菜。"],["田中会做什么菜？","水果沙拉。"],["他们今天晚上在哪儿吃饭？","在美京家。"],["今天晚上他们吃什么？","韩国菜和水果沙拉，还尝美京做的红酒。"]]},{"title":"08-2 · Ngoại ngữ và tài nấu ăn","d":1,"questions":[["卡玛拉怎么知道田中喜欢吃韩国菜？","听美京说的。"],["红酒是谁做的？","美京做的。"],["美京除了汉语以外，还会说什么外语？","英语和日语。"],["卡玛拉觉得自己的汉语怎么样？","她说自己只会说一点儿汉语。"]]}];app.innerHTML=intro('LUYỆN NGHE · BÀI 8','Nấu ăn và trò chuyện về ngoại ngữ.','Bốn file Q2B8 bạn cung cấp, kèm bản ghi BTNC và câu tự luyện.')+'<div class="notice">Các file Q2B8 thuộc bộ BTNC. NC1–NC3 được đối chiếu với PDF bài 8. Chưa xác nhận bản thu tương ứng mã 08-1, 08-2, 08-3 trong giáo trình.</div>'+['Q2B8.mp3','Q2B8.NC1.MP3','Q2B8.NC2.MP3','Q2B8.NC3.MP3'].map((file,i)=>'<article class="card grammar"><h3>'+file+'</h3><audio controls preload="none" src="audio/'+file+'"></audio><label>Tốc độ <select data-lesson8-audio="'+i+'" aria-label="Tốc độ '+file+'"><option value="0.75">0.75×</option><option value="1" selected>1×</option><option value="1.25">1.25×</option></select></label>'+lesson8BTNCMarkup(file)+'</article>').join('')+'<h2>Luyện thêm theo văn bản giáo trình</h2>'+lesson2VoiceControls()+groups.map(g=>'<article class="card grammar"><h2>'+g.title+'</h2><button class="btn secondary" data-lesson8-listen="'+g.d+'">▶ Nghe toàn hội thoại bằng giọng thiết bị</button>'+(g.tf?'<h3>Đúng / sai</h3>'+g.tf.map(([q,a])=>'<details class="lesson2-answer-key"><summary>'+q+'</summary><p>'+a+'</p></details>').join(''):'')+'<h3>Nghe và trả lời</h3>'+g.questions.map(([q,a])=>'<details class="lesson2-answer-key"><summary>'+q+'</summary><p>'+a+'</p></details>').join('')+'<p class="sub">Đáp án theo văn bản hội thoại, không phải theo audio BTNC.</p></article>').join('')+'<article class="card grammar"><h2>08-3 · Bài nghe mở rộng</h2><p class="notice">Chưa xác nhận bản thu tương ứng 08-3 nên phần này chưa chấm điểm.</p><h3>Đúng / sai</h3><ol><li>男的在听歌。</li><li>男的不会说法语。</li><li>女的会说法语。</li><li>他们周末要一起去唱歌。</li></ol><h3>Chọn đáp án</h3><ol><li>男的会说什么外语？<br>A. 法语　B. 汉语和法语　C. 英语和汉语</li><li>男的觉得法语怎么样？<br>A. 很难　B. 不好听　C. 有点儿难</li><li>女的会说什么外语？<br>A. 英语　B. 汉语　C. 英语和汉语</li><li>女的会唱什么歌？<br>A. 中文歌　B. 法语歌　C. 英文歌</li></ol></article>'+lesson8References(11,13);bindLesson8BTNC();document.querySelectorAll('[data-lesson8-audio]').forEach(s=>s.onchange=()=>document.querySelectorAll('audio')[Number(s.dataset.lesson8Audio)].playbackRate=Number(s.value));document.querySelectorAll('audio').forEach(a=>a.onplay=()=>{stopWordAudio();document.querySelectorAll('audio').forEach(b=>{if(a!==b)b.pause();});});bindLesson2Voice(lesson8Data.dialogues[0][1].map(l=>l[1]).join(' '));document.querySelectorAll('[data-lesson8-listen]').forEach(b=>b.onclick=()=>lesson2Speak(lesson8Data.dialogues[Number(b.dataset.lesson8Listen)][1].map(l=>l[1]).join(' ')));}
function renderLesson8Shop(area){const saved=state.lesson8Interview||{};area.innerHTML='<article class="card grammar"><h2>Phỏng vấn bạn học</h2><p>Hỏi tên, kỹ năng hoặc sở thích rồi bổ sung thông tin bằng 除了……以外，还……. Nếu trả lời không, chuyển sang bạn tiếp theo. Đây là câu trả lời mở.</p>'+[['name','Tên bạn học','小明'],['kind','会 hoặc 喜欢','会'],['first','Kỹ năng / sở thích thứ nhất','说英语'],['extra','Thêm kỹ năng / sở thích','说法语']].map(([key,label,hint])=>'<label for="lesson8Interview'+key+'">'+label+'</label><input class="lesson2-answer" id="lesson8Interview'+key+'" data-lesson8-interview="'+key+'" placeholder="'+hint+'" value="'+esc(saved[key]||'')+'">').join('')+'<button class="btn" id="lesson8InterviewMake">Tạo báo cáo tham khảo</button><p id="lesson8InterviewOutput" style="white-space:pre-line;line-height:2"></p></article>'+lesson8References(9,10);document.querySelectorAll('[data-lesson8-interview]').forEach(input=>input.oninput=e=>{state.lesson8Interview=state.lesson8Interview||{};state.lesson8Interview[input.dataset.lesson8Interview]=e.target.value;save();});document.querySelector('#lesson8InterviewMake').onclick=()=>{const p=state.lesson8Interview||{},kind=p.kind==='喜欢'?'喜欢':'会';document.querySelector('#lesson8InterviewOutput').textContent=(p.name||'小明')+kind+(p.first||'说英语')+'，除了'+(p.first||'说英语')+'以外，还'+kind+(p.extra||'说法语')+'。';};}
for(const[route,handler]of Object.entries({home:lesson8Home,grammar:lesson8Grammar,dialogue:lesson8Dialogue,practice:lesson8Practice,listening:lesson8Listening}))pages[route]=function(){if(state.lesson==='8')handler();else lesson8PreviousPages[route]();};
pages.writing=function(){lesson8PreviousPages.writing();if(state.lesson!=='8')return;document.querySelector('#app .eyebrow').textContent='LUYỆN VIẾT · BÀI 8';const chars=[...new Set(lesson8Data.rows.map(r=>r[0]).join('').split('').filter(c=>/[\u3400-\u9fff]/.test(c)))];document.querySelector('#model').innerHTML=chars.map(c=>'<option>'+c+'</option>').join('');document.querySelector('#modelchar').textContent=chars[0];};
const lesson8SkillTasks=[{label:'唱歌 · 中文歌、日文歌',action:'唱歌',detail:'唱中文歌和日文歌'},{label:'跳舞 · 街舞、日本舞',action:'跳舞',detail:'跳街舞和日本舞'}];
function gradeLesson8Skill(index,kind,draft){const t=lesson8SkillTasks[index],variants=kind===0?['你会'+t.action+'吗','你会不会'+t.action]:kind===1?['我会'+t.action,'会'+t.action,'会']:['我会'+t.detail,t.detail];return variants.some(a=>compareHanzi(draft,a).correct);}
function renderLesson8Skills(area){const saved=state.lesson8Exercises?.skills||{};area.innerHTML='<article class="card grammar"><h2>Kỹ năng theo ảnh</h2><p>Hỏi và trả lời khẳng định theo hai bộ từ gợi ý trong sách.</p><img loading="lazy" src="images/lesson8/source-4.png" alt="Ảnh nấu ăn, hát và múa của bài luyện trang 94" style="display:block;max-width:100%;width:440px;margin:12px auto">'+lesson8SkillTasks.map((t,i)=>'<h3>'+(i+1)+'. '+t.label+'</h3>'+['Hỏi bạn có biết làm không','Trả lời: tôi biết','Nói cụ thể biết hát / múa những gì'].map((q,j)=>'<label for="lesson8Skill'+i+'-'+j+'">'+q+'</label><input class="lesson2-answer" lang="zh-CN" id="lesson8Skill'+i+'-'+j+'" value="'+esc(saved[i]?.drafts?.[j]||'')+'"><p id="lesson8SkillFeedback'+i+'-'+j+'" role="status"></p>').join('')+'<button class="btn secondary" data-lesson8-skill="'+i+'">Kiểm tra</button>').join('')+'</article>';document.querySelectorAll('[data-lesson8-skill]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.lesson8Skill),t=lesson8SkillTasks[i],drafts=[],results=[];for(let j=0;j<3;j++){const draft=document.querySelector('#lesson8Skill'+i+'-'+j).value,correct=gradeLesson8Skill(i,j,draft);drafts.push(draft);results.push(correct);document.querySelector('#lesson8SkillFeedback'+i+'-'+j).textContent=correct?'✓ Chính xác':'Mẫu tham khảo: '+['你会'+t.action+'吗？','我会'+t.action+'。','我会'+t.detail+'。'][j];}state.lesson8Exercises=state.lesson8Exercises||{};state.lesson8Exercises.skills=state.lesson8Exercises.skills||{};state.lesson8Exercises.skills[i]={drafts,results};save();});}
const lesson8ExtensionTasks=[['唱英文歌','唱中文歌'],['吃中国菜','吃韩国菜'],['看电影','看书'],['喝茶','喝咖啡']];
function lesson8ExtensionAnswer(first,extra){return '除了'+first+'以外，我还喜欢'+extra;}
function gradeLesson8Extension(index,draft){const [first,extra]=lesson8ExtensionTasks[index],a=lesson8ExtensionAnswer(first,extra);return [a,'我'+a,a.replace('以外','')].some(v=>compareHanzi(draft,v).correct);}
function renderLesson8Extension(area){const saved=state.lesson8Exercises?.extension||{};area.innerHTML='<article class="card grammar"><h2>Ngoài… còn thích…</h2><p>Dựa theo ảnh trang 95, ghép hoạt động có sẵn với một sở thích bổ sung. Hoạt động thứ hai dưới đây là gợi ý để luyện mẫu câu; sách để mở.</p><img loading="lazy" src="images/lesson8/source-5.png" alt="Ảnh hát, ăn món Trung, xem phim và uống trà ở trang 95" style="display:block;max-width:100%;width:440px;margin:12px auto">'+lesson8ExtensionTasks.map(([first,extra],i)=>'<label for="lesson8Extension'+i+'">'+(i+1)+'. '+first+' + '+extra+'</label><input class="lesson2-answer" lang="zh-CN" id="lesson8Extension'+i+'" value="'+esc(saved[i]?.draft||'')+'"><p id="lesson8ExtensionFeedback'+i+'" role="status"></p>').join('')+'<button class="btn" id="lesson8ExtensionCheck">Kiểm tra</button></article>';document.querySelector('#lesson8ExtensionCheck').onclick=()=>{const records={};lesson8ExtensionTasks.forEach(([first,extra],i)=>{const draft=document.querySelector('#lesson8Extension'+i).value,correct=gradeLesson8Extension(i,draft);records[i]={draft,correct};document.querySelector('#lesson8ExtensionFeedback'+i).textContent=correct?'✓ Chính xác':'Mẫu tham khảo: '+lesson8ExtensionAnswer(first,extra)+'。';});state.lesson8Exercises=state.lesson8Exercises||{};state.lesson8Exercises.extension=records;save();};}
render();
